export function newbirthPage(){return "<div class=\"page-shell dao-reading reading-single-column nb-page\"><nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"/read/\">首页</a><span>/</span><a href=\"/read/tian/\">天道</a><span>/</span><span>变化</span><span>/</span><span aria-current=\"page\">化：新生</span></nav><figure class=\"nb-hero\"><img src=\"/assets/newbirth/newbirth-v1.png\" width=\"1916\" height=\"821\" alt=\"晨光照亮山谷，老树枝头开满白花。\"></figure><header class=\"page-heading\"><p class=\"eyebrow\">TIAN / 变化 · 3.3</p><h1>化：新生</h1><p class=\"page-intro\">变化怎样产生新的形式、能力与可能？</p></header><details class=\"reading-contents\"><summary><span>本页目录</span></summary><nav><a href=\"#outline\">本章主线</a><a href=\"#stability\">稳定与失稳</a><a href=\"#emergence\">重组与涌现</a><a href=\"#exploration\">探索与扩展</a><a href=\"#selection\">选择与积累</a><a href=\"#direction\">方向与价值</a></nav></details><article class=\"prose nb-content\">\n<section class=\"section\" id=\"outline\"><h2>从既有秩序，到新的可能</h2><p class=\"lead\">中心张力：结构使事物得以存在，也可能限制它继续发展。</p>\n<div class=\"chapter-row\"><b>3.1 易：流变</b><span>理解持续变化的本质。</span></div><div class=\"chapter-row\"><b>3.2 复：节律</b><span>理解变化中的往复、阶段与时机。</span></div><div class=\"chapter-row\"><b>3.3 化：新生</b><span>理解已有存在怎样形成新的组织、性质与发展条件。</span></div>\n<div class=\"meanings\"><div class=\"meaning\"><h3>新形式</h3><p>组成与关系改变，形成不同的组织方式。</p></div><div class=\"meaning\"><h3>新能力</h3><p>新的组织关系，使整体能够做到此前做不到的事。</p></div><div class=\"meaning\"><h3>新可能</h3><p>新成果改变后续条件，更多事情因此变得可行。</p></div></div>\n<div class=\"statement\"><p><strong>核心主张</strong><br/>在一定条件下，既有结构通过相互作用与重组，形成新的性质和能力；其中一些变化经过反馈、选择与积累，改变后续发展的起点，打开此前无法实现的可能。</p></div>\n<div class=\"roadmap\"><a href=\"#stability\"><span>01 / 存在的条件</span>稳定与失稳</a><a href=\"#emergence\"><span>02 / 新性质的形成</span>重组与涌现</a><a href=\"#exploration\"><span>03 / 可行范围的改变</span>探索与扩展</a><a href=\"#selection\"><span>04 / 成果的延续</span>选择与积累</a></div><p class=\"loop\">留下的成果，成为下一轮变化的起点 ↗</p><p class=\"subtle\">四个环节用于组织研究，可以交叠、回返；具体过程未必依次经过全部环节。</p>\n</section>\n<section class=\"section\" id=\"stability\"><h2>稳定与失稳</h2><p class=\"lead\">秩序靠什么维持？原有的维持条件改变后，会发生什么？</p>\n<figure class=\"diagram\"><h3>结构的两种作用</h3><div class=\"relation\"><div><strong>使事物持续存在</strong><p>交换、协作、资源与反馈，支持既有组织方式。</p></div><div><strong>使改变受到限制</strong><p>既有分工、利益与评价方式，也会筛去某些新方向。</p></div></div><figcaption>关系示意。热力学中的能量交换与企业中的资源配置，分别按各自机制解释。</figcaption></figure>\n<div class=\"two-col\"><div><h3>核心内容</h3><ul><li><b>熵增与造序：</b>讨论物理秩序形成、维持和瓦解的条件；熵增保留明确的热力学含义。</li><li><b>开放与交换：</b>特定远离平衡的系统可形成、维持耗散结构；交换本身不足以保证造序。</li><li><b>惯性与锁定：</b>维持成功的结构，也可能持续排斥尚不符合当前要求的新事物。</li></ul></div><div><h3>进一步理解</h3><ul><li>表面的稳定，是怎样不断被维持的？</li><li>什么条件改变，才会使原有状态难以维持？</li><li>旧结构中，哪些应保留，哪些需调整，哪些可能被放下？</li></ul></div></div>\n<div class=\"bridge\">旧结构松动之后，新的组织关系怎样形成？新生也可能在仍然稳定的结构内部逐渐发生。</div>\n</section>\n<section class=\"section\" id=\"emergence\"><h2>重组与涌现</h2><p class=\"lead\">什么关系发生改变，使整体具备此前没有的性质与能力？</p>\n<figure class=\"diagram\"><h3>从“更多”追问到“不同”</h3><div class=\"flow\"><div class=\"node\">数量或条件改变<small>什么在积累？</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\">相互作用与组织改变<small>哪些关系被重建？</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\">整体呈现新性质<small>现在能够做什么？</small></div></div><figcaption>积累未必引起结构改变；有些新性质逐渐形成，有些转变呈现临界跃迁。</figcaption></figure>\n<div class=\"two-col\"><div><h3>核心内容</h3><ul><li><b>量变与质变：</b>区分数量增加、程度增强与组织方式改变。</li><li><b>非线性与临界：</b>研究何时小变化会产生不成比例的影响，以及哪些条件参与转变。</li><li><b>重组、合作与涌现：</b>说明组成部分如何通过关系形成整体能力；自组织放在具体过程中解释。</li></ul></div><div><h3>进一步理解</h3><ul><li>新的性质具体是什么，以什么表现辨认？</li><li>只增加同样的部分，为什么可能仍然做不到？</li><li>哪些转变需要临界条件，哪些可以渐进完成？</li></ul></div></div>\n<div class=\"bridge\">一种新能力形成之后，后续能够发生的事也可能随之改变。</div>\n</section>\n<section class=\"section\" id=\"exploration\"><h2>探索与扩展</h2><p class=\"lead\">有些道路，需要走出一段之后，才成为可以继续走的路。</p>\n<div class=\"seed-grid\"><div class=\"seed\"><h3>发现已有可能</h3><p>条件已经具备，只是我们还不知道这条路径。</p></div><div class=\"seed\"><h3>形成新的可行条件</h3><p>行动带来新知识、工具、技能或关系，使此前做不到的事情变得可行。</p></div></div>\n<figure class=\"diagram\"><h3>探索中的“踏脚石” · 概念示意</h3>\n<div class=\"possibility-path\"><div class=\"node\">当前能做到的事<small>起点与已有条件</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\" id=\"path-middle\">探索中的新能力<small>眼下未必接近终点</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\" id=\"path-end\">打开新的可行方向<small>成为继续探索的条件</small></div></div><p aria-live=\"polite\" class=\"path-detail\" id=\"path-detail\">保留有意义的中间成果，可能使新的方向出现。探索也可能没有预期回报。</p><figcaption>图示比较筛选逻辑，不表示探索一定成功，也不表示目标与计划应被普遍放弃。</figcaption></figure>\n<div class=\"two-col\"><div><h3>核心内容</h3><ul><li><b>探索与踏脚石：</b>关键中间成果未必看起来接近最终目标。</li><li><b>能力改变可能：</b>一次创造可以成为下一次创造的工具和条件。</li><li><b>已知与未知：</b>区分尚未被认识的可能，与在具体发展中才形成的可行条件。</li></ul></div><div><h3>进一步理解</h3><ul><li>什么成果值得保留，即使暂时看不出最终用途？</li><li>行动改变了认识，还是也改变了现实条件？</li><li>怎样给探索留下空间，又用反馈检验它的价值？</li></ul></div></div>\n<div class=\"bridge\">新方向出现之后，什么使它能够留下、发展，并影响未来？</div>\n</section>\n<section class=\"section\" id=\"selection\"><h2>选择与积累</h2><p class=\"lead\">从“出现不同”，到“留下成果”，中间还有哪些过程？</p>\n<figure class=\"diagram\"><h3>积累改变下一轮的起点</h3><div class=\"flow\"><div class=\"node\">出现不同<small>变化与尝试</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\">反馈与选择<small>有些保留，有些消失</small></div><span aria-hidden=\"true\" class=\"arrow\">→</span><div class=\"node\">记忆与传递<small>经验、技能、知识、制度</small></div></div><p class=\"loop\">↳ 保留下来的内容，改变下一轮的条件与选择。</p><figcaption>不同领域的选择机制各有含义。积累也可能强化错误、形成锁定。</figcaption></figure>\n<div class=\"two-col\"><div><h3>核心内容</h3><ul><li><b>反馈：</b>结果如何参与后续调整；放大和抑制都需看具体作用。</li><li><b>选择与保留：</b>解释哪些变化能够持续、扩散，哪些会消失。</li><li><b>积累与路径依赖：</b>过去留下的成果和限制，共同改变后续起点。</li></ul></div><div><h3>进一步理解</h3><ul><li>是谁、依什么条件选择？被保留的内容是什么？</li><li>经历怎样通过记忆、技能或制度留下？</li><li>反复何时形成发展，何时只是强化旧模式？</li></ul></div></div>\n<details class=\"nb-fold\"><summary>旧稿“螺旋进化”的安放</summary><p>3.2辨认往复中的差异；本节解释差异如何被保留，并改变下一轮起点。“螺旋”描述某些特定的积累过程，方向是否向上放到结尾独立讨论。</p></details>\n<div class=\"bridge\">能够留下、能够扩散，是否就意味着更好？</div>\n</section>\n<section class=\"section\" id=\"direction\"><h2>演化的方向与价值完成</h2><p class=\"lead\">新的是否更好？发展究竟以什么衡量？</p>\n<div class=\"closing\"><h3>保留三个方向问题</h3><ul><li><b>“向上”：</b>能力增强、规模扩大、结构复杂，分别意味着什么？它们与价值的关系是什么？</li><li><b>“向全”：</b>怎样理解更多样、更充分的表达，以及不同存在之间的共同成就？</li><li><b>“价值完成”：</b>借赛斯继续追问存在的独特品质怎样展开；其含义不以数量增长或寿命延长穷尽。</li></ul></div>\n<div class=\"statement\"><p><strong>接回全篇已确认的主旨</strong><br/>变化的本质，是源头在万物之中持续地表达、创造并体验自己。</p></div><p class=\"subtle\">理解发展方向，需要进一步辨认表达的品质与价值；前述过程并不保证发展必然向上。</p>\n<details class=\"nb-fold\"><summary>可放在结尾的古典旁读</summary><blockquote>臭腐復化為神奇，神奇復化為臭腐。<cite>《庄子·知北游》</cite></blockquote><p>连读生死、气的聚散与人的好恶，保留“化”的双向性。此处用于打开方向与评价问题，不把所有价值区别一并取消。</p></details>\n</section>\n</article><nav class=\"next-route\"><a href=\"/read/concept/probability/\">上一篇：复：节律</a><a href=\"/read/tian/\">返回天道目录</a></nav></div>";}
